// Signed, SHA-256-pinned one-liner (valid 24 h) generated by the backend for Linux assets; see api/routers/inventory.py.
function OneLiner({ assetName }) {
  const [state, setState] = useState({ loading: true })
  const [copied, setCopied] = useState(false)
  useEffect(() => {
    let cancelled = false
    axios.get(`${API_BASE}/inventory/${encodeURIComponent(assetName)}/agent-install-command`)
      .then((r) => { if (!cancelled) setState({ data: r.data }) })
      .catch((e) => { if (!cancelled) setState({ error: e.response?.data?.detail || e.message }) })
    return () => { cancelled = true }
  }, [assetName])
  if (state.loading) return <p className="text-slate-500"># Generando comando firmado…</p>
  if (state.error) return <p className="text-amber-400"># Comando de una línea no disponible: {state.error}</p>
  const copy = () => navigator.clipboard?.writeText(state.data.command).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000) })
  return (
    <>
      <p className="text-slate-500 mb-1"># Ejecutar en el servidor (descarga, verifica el SHA-256 y ejecuta como root). Válido hasta {state.data.expires_at.replace('T', ' ').slice(0, 16)}</p>
      <p className="break-all select-all">{state.data.command}</p>
      <button onClick={copy} className="mt-2 text-[12px] font-bold text-indigo-300 hover:text-white">{copied ? 'Copiado' : 'Copiar comando'}</button>
    </>
  )
}

